<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useGameStore } from '@/stores/game.store';
import { GAME_BY_ID } from '@/data/games';

const route = useRoute();
const router = useRouter();
const gameStore = useGameStore();
const sessionId = computed(() => route.params.sessionId as string);
const routeGameId = computed(() => sessionId.value.replace(/^demo-/, '').toUpperCase());
const activeGameId = computed(() => gameStore.session?.game_id || (GAME_BY_ID[routeGameId.value] ? routeGameId.value : 'WEREWOLF'));
const activeGame = computed(() => GAME_BY_ID[activeGameId.value] || GAME_BY_ID.WEREWOLF);
const isDemo = computed(() => sessionId.value.startsWith('demo-'));
const selectedCard = ref<number | null>(null);
const actionMessage = ref('Đến lượt của bạn · chọn một hành động');
const showRules = ref(false);
const demoHand = ref([
  { rank: 'A', suit: '♠', tone: 'black' }, { rank: 'K', suit: '♥', tone: 'red' }, { rank: '10', suit: '♣', tone: 'black' }, { rank: '8', suit: '♦', tone: 'red' }, { rank: '7', suit: '♠', tone: 'black' }, { rank: '3', suit: '♥', tone: 'red' }
]);

const currentState = computed(() => gameStore.gameState as any);
const myHand = computed(() => isDemo.value ? demoHand.value : currentState.value?.myHand || []);
const isCardGame = computed(() => activeGame.value.category === 'cards');
const isBoardGame = computed(() => activeGame.value.category === 'board');
const topCard = computed(() => currentState.value?.discardPile?.at(-1) || { rank: 'Q', suit: '♣', tone: 'black' });

onMounted(async () => {
  if (!isDemo.value) {
    try {
      await gameStore.fetchGameState(sessionId.value);
      gameStore.subscribeToSession(sessionId.value);
    } catch { actionMessage.value = 'Kết nối bàn tạm thời gián đoạn · đang ở chế độ xem'; }
  }
});

onUnmounted(() => { if (!isDemo.value) gameStore.unsubscribeFromSession(); });

const chooseCard = (index: number | string) => { const cardIndex = Number(index); selectedCard.value = selectedCard.value === cardIndex ? null : cardIndex; actionMessage.value = selectedCard.value === null ? 'Đến lượt của bạn · chọn một hành động' : `Đã chọn lá ${cardIndex + 1} · xác nhận để đánh`; };
const drawCard = async () => {
  if (!isDemo.value) { try { await gameStore.playAction(sessionId.value, { type: 'DRAW_CARD' }); } catch { actionMessage.value = 'Nước đi chưa hợp lệ'; } return; }
  demoHand.value.push({ rank: '5', suit: '♦', tone: 'red' }); actionMessage.value = 'Bạn đã rút 1 lá · lượt vẫn được giữ';
};
const playCard = async () => {
  if (selectedCard.value === null) { actionMessage.value = 'Chọn một lá trước khi xác nhận'; return; }
  if (!isDemo.value) { try { await gameStore.playAction(sessionId.value, { type: 'PLAY_CARD', card: myHand.value[selectedCard.value] }); } catch { actionMessage.value = 'Lá này chưa thể đánh'; } return; }
  demoHand.value.splice(selectedCard.value, 1); selectedCard.value = null; actionMessage.value = 'Nước đi đã được ghi nhận · đối thủ đang suy nghĩ';
};
</script>

<template>
  <div class="arena-page">
    <header class="arena-header"><div class="arena-brand"><button @click="router.push('/rooms')" class="back-button"><i class="bi bi-arrow-left"></i></button><div class="brand-glyph-small"><i class="bi bi-diamond-half"></i></div><div><strong>LuNu Arena</strong><small>{{ activeGame.name }} · {{ isDemo ? 'Bàn mẫu' : `Session ${sessionId.slice(0, 8)}` }}</small></div></div><div class="arena-center-status"><span class="live-dot"></span><strong>Trực tiếp</strong><span>Ván #24</span><span class="status-divider"></span><span>00:12:42</span></div><div class="arena-actions"><button class="arena-icon"><i class="bi bi-volume-up"></i></button><button class="arena-icon" @click="showRules = !showRules"><i class="bi bi-journal-text"></i></button><button class="leave-arena" @click="router.push('/rooms')">Rời bàn</button></div></header>
    <div class="arena-layout">
      <main class="arena-board-wrap"><div class="arena-table" :class="activeGame.category"><div class="arena-table-inner"><div class="table-ring"></div><div class="opponent opponent-top"><div class="opponent-avatar">K</div><div><strong>Khanh Vu</strong><small><span class="mini-live"></span> Đang suy nghĩ</small></div><span class="opponent-count">6 <small>lá</small></span></div><div class="opponent opponent-left"><div class="opponent-avatar">M</div><div><strong>Mỹ Hạnh</strong><small>Ghế 2 · 1.250 xu</small></div></div><div class="opponent opponent-right"><div class="opponent-avatar">A</div><div><strong>An Khang</strong><small>Ghế 4 · 890 xu</small></div></div><div class="board-center"><div v-if="isCardGame" class="card-piles"><div class="deck-stack"><span></span><span></span><div class="back-card"><i class="bi bi-diamond-half"></i></div><small>RÚT BÀI</small></div><div class="center-separator"><span></span><i class="bi bi-arrow-right"></i><span></span></div><div class="playing-card face-up" :class="topCard.tone"><span>{{ topCard.rank }}</span><strong>{{ topCard.suit }}</strong><small>{{ topCard.rank }}</small></div></div><div v-else class="board-game-center"><div class="board-emblem"><i :class="`bi ${activeGame.icon}`"></i></div><strong>{{ activeGame.name }}</strong><small>{{ isBoardGame ? 'Bàn cờ đang đồng bộ' : 'Đêm đầu tiên · thảo luận mở' }}</small></div><div class="pot-display"><small>{{ isCardGame ? 'POT HIỆN TẠI' : 'TRẠNG THÁI' }}</small><strong>{{ isCardGame ? '2.450 xu' : 'ĐANG DIỄN RA' }}</strong></div></div><div class="turn-message"><span class="turn-dot"></span>{{ actionMessage }}</div><div class="opponent opponent-bottom"><div class="my-avatar">L</div><div><strong>Bạn · LuNu</strong><small>{{ isCardGame ? `${myHand.length} lá trên tay` : 'Ghế của bạn' }}</small></div><span class="my-balance">+240 xu</span></div></div></div><div class="arena-bottom-bar"><div class="bottom-stat"><i class="bi bi-shield-check"></i><span><strong>Bàn công bằng</strong><small>Kết quả được xác thực</small></span></div><div class="bottom-stat"><i class="bi bi-wifi"></i><span><strong>Ổn định</strong><small>38 ms</small></span></div><div class="bottom-help ms-auto"><i class="bi bi-lightbulb"></i> Gợi ý nước đi đang tắt</div></div>
      </main>
      <aside class="arena-side-panel"><div class="side-panel-header"><div><div class="eyebrow">Ván đang diễn ra</div><h2>{{ activeGame.name }}</h2></div><span class="round-chip">ROUND 04</span></div><div class="score-line"><span>Pot / giải thưởng</span><strong class="text-gold">2.450 xu</strong></div><div class="score-line"><span>Phí bàn</span><strong>50 xu</strong></div><div class="panel-divider"></div><div v-if="isCardGame" class="action-panel"><div class="action-title"><span>Lá bài của bạn</span><small>{{ myHand.length }} lá</small></div><div class="hand-preview"><button v-for="(card, index) in myHand.slice(0, 4)" :key="index" class="mini-card" :class="card.tone" @click="chooseCard(index)"><span>{{ card.rank }}</span><strong>{{ card.suit }}</strong></button><span v-if="myHand.length > 4" class="more-cards">+{{ myHand.length - 4 }}</span></div><div class="action-buttons"><button class="btn action-primary" @click="playCard"><i class="bi bi-hand-index-thumb me-2"></i>Đánh lá đã chọn</button><button class="btn action-secondary" @click="drawCard"><i class="bi bi-plus-lg me-2"></i>Rút một lá</button></div></div><div v-else class="action-panel board-action"><div class="action-title"><span>Trợ giúp bàn</span><small>Đang bật</small></div><div class="ai-option"><span class="ai-icon"><i class="bi bi-stars"></i></span><div><strong>Gợi ý nước đi</strong><small>Đề xuất chiến thuật theo trình độ</small></div><i class="bi bi-toggle-on text-mint ms-auto fs-5"></i></div><button class="btn action-secondary w-100 mt-3"><i class="bi bi-flag me-2"></i>Đề nghị hòa</button></div><div class="panel-divider"></div><div class="activity-feed"><div class="action-title"><span>Nhật ký bàn</span><button class="feed-more">Xem tất cả</button></div><div class="feed-item"><span class="feed-avatar gold">K</span><span><strong>Khanh Vu</strong> đã theo cược</span><small>12s</small></div><div class="feed-item"><span class="feed-avatar mint">M</span><span><strong>Mỹ Hạnh</strong> đã bỏ lượt</span><small>28s</small></div><div class="feed-item"><span class="feed-avatar purple">A</span><span><strong>An Khang</strong> vào xem bàn</span><small>1m</small></div></div><div class="spectator-note"><i class="bi bi-eye"></i><span><strong>9 người</strong> đang theo dõi bàn này</span></div></aside>
    </div>
    <div v-if="isCardGame" class="player-hand"><div class="hand-label"><span class="eyebrow">Tay bài của bạn</span><small>Chọn lá rồi xác nhận nước đi</small></div><div class="hand-cards"><button v-for="(card, index) in myHand" :key="index" class="playing-card hand-card" :class="[{ selected: selectedCard === index }, card.tone]" @click="chooseCard(index)"><span>{{ card.rank }}</span><strong>{{ card.suit }}</strong><small>{{ card.rank }}</small></button><div class="hand-actions"><button class="btn btn-gold" @click="playCard" :disabled="selectedCard === null"><i class="bi bi-check2 me-2"></i>Xác nhận</button><button class="btn btn-quiet" @click="drawCard">Rút bài</button></div></div></div>
    <div v-if="showRules" class="rules-drawer"><div class="drawer-inner"><button class="close-button" @click="showRules = false"><i class="bi bi-x-lg"></i></button><div class="eyebrow">Luật {{ activeGame.name }}</div><h2>Chơi đúng nhịp bàn</h2><p>{{ activeGame.description }}</p><div v-for="(rule, index) in activeGame.rules" :key="rule" class="drawer-rule"><span>0{{ index + 1 }}</span><strong>{{ rule }}</strong></div></div></div>
  </div>
</template>

